    "trainingNote": "'إفساح طريق متعدد الاتجاهات' تُستخدم عادة مع B1 في تقاطعات من نوع 'كل الاتجاهات عليها واجب إفساح الطريق' — يجب حينها تطبيق قاعدة الأولوية العامة (كاليمين) بين المركبات المتزامنة.",
